(() => {
  const results = {};
  // All text nodes containing 'Availability'
  const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
  const texts = [];
  let node;
  while ((node = walker.nextNode())) {
    const t = node.textContent;
    if (t && t.includes('Availability')) texts.push(t.trim());
  }
  results.textsContainingAvailability = [...new Set(texts)];
  // Panel containers
  const panels = document.querySelectorAll('[data-testid^="panel"], .panel-container, .panel-wrapper');
  results.panelContainerCount = panels.length;
  // Any collapsed rows
  const rows = document.querySelectorAll('[data-testid^="row"]');
  results.rowCount = rows.length;
  // All headings of any level inside main
  const headings = [...document.querySelectorAll('main h1, main h2, main h3, main h4')].map(h => h.textContent.trim());
  results.allHeadingsInMain = headings;
  return JSON.stringify(results);
})()

(() => {
  const el = document.querySelector('[aria-label="Select a data source"]') || document.querySelector('input[aria-label*="data source" i]');
  if (!el) return 'not found';
  const container = el.closest('div');
  return JSON.stringify({inputValue: el.value, containerText: container ? container.textContent.trim() : null, placeholder: el.placeholder});
})()
